package me.xjanua.aitranswatch.controller;
import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import me.xjanua.aitranswatch.dto.RestResponse; import me.xjanua.aitranswatch.dto.driver.*; import me.xjanua.aitranswatch.enums.DriverStatus; import me.xjanua.aitranswatch.service.DriverService;
@RestController @RequestMapping("/api/drivers") public class DriverController {private final DriverService service;public DriverController(DriverService service){this.service=service;}@GetMapping public RestResponse<Page<DriverResponse>> list(@RequestParam(required=false)String search,@RequestParam(required=false)DriverStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return RestResponse.success(service.list(search,status,PageRequest.of(page,Math.min(Math.max(size,1),100),Sort.by("employeeCode").ascending())));}@GetMapping("/{id}")public RestResponse<DriverResponse> get(@PathVariable UUID id){return RestResponse.success(service.get(id));}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')")public ResponseEntity<RestResponse<DriverResponse>> create(@Valid @RequestBody DriverRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(RestResponse.success(service.create(request)));}@PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')")public RestResponse<DriverResponse> update(@PathVariable UUID id,@Valid @RequestBody DriverRequest request){return RestResponse.success(service.update(id,request));}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')")public ResponseEntity<Void> suspend(@PathVariable UUID id){service.suspend(id);return ResponseEntity.noContent().build();}}
